// Original local renderer: pixel field, radial reveal, perimeter beam and cursor ripple.
export function mountPixelButtons(root=document.getElementById('root')){const reduced=matchMedia('(prefers-reduced-motion: reduce)'),instances=new Map();let scanFrame=null;function attach(button){if(instances.has(button))return;const canvas=document.createElement('canvas');canvas.className='muse-pixel-canvas';canvas.setAttribute('aria-hidden','true');const ctx=canvas.getContext('2d');if(!ctx)return;let width=0,height=0,dpr=1,frame=null,hover=0,target=0,mx=.5,my=.5,last=0,visible=true,clock=0,ripples=[];const data={destroy,canvas};instances.set(button,data);button.classList.add('muse-pixel-button');button.appendChild(canvas);function resize(){const rect=button.getBoundingClientRect();width=rect.width;height=rect.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);render(0);wake()}function render(dt){if(!width||!height)return;clock+=dt;hover+=(target-hover)*(1-Math.exp(-Math.max(dt,16)/130));if(reduced.matches)hover=0;ctx.clearRect(0,0,width,height);const off=button.disabled;const spacing=7,cell=2.35,px=mx*width,py=my*height;const radius=hover*Math.hypot(width,height)*1.2;const glow=ctx.createRadialGradient(px,py,0,px,py,Math.max(1,radius));glow.addColorStop(0,`rgba(220,220,220,${off?0:hover*.28})`);glow.addColorStop(.65,`rgba(220,220,220,${off?0:hover*.14})`);glow.addColorStop(1,'rgba(220,220,220,0)');ctx.fillStyle=glow;ctx.fillRect(0,0,width,height);for(let y=5;y<height;y+=spacing)for(let x=5;x<width;x+=spacing){const hash=Math.sin(x*12.9898+y*78.233)*43758.5453,seed=hash-Math.floor(hash);const shimmer=.45+.3*Math.sin(clock*.0015+seed*6.28);const dist=Math.hypot(x-px,y-py),reveal=radius>0?Math.max(0,Math.min(1,(radius-dist)/30)):0;const cursorWave=Math.sin(dist*.09-clock*.003)*reveal*.12;const wave=Math.exp(-Math.pow((x/width-((clock*.00013)%1.4-.2))/.22,2));let brightness=.12+shimmer*.30+wave*.25+reveal*.38+cursorWave;for(const ripple of ripples){const age=clock-ripple.time,rr=age*.48;brightness+=Math.exp(-Math.abs(Math.hypot(x-ripple.x,y-ripple.y)-rr)/9)*Math.max(0,1-age/800)*.7}const alpha=off?.04:Math.min(.95,brightness);const size=cell+reveal*.6;ctx.shadowBlur=off?0:3.5+reveal*3;ctx.shadowColor='rgba(220,220,220,.65)';ctx.fillStyle=`rgba(${Math.round(140+brightness*100)},${Math.round(140+brightness*100)},${Math.round(140+brightness*100)},${alpha})`;ctx.beginPath();ctx.arc(x,y,size*.48,0,Math.PI*2);ctx.fill()}ctx.shadowBlur=0;const halo=ctx.createRadialGradient(width/2,height/2,5,width/2,height/2,width*.42);halo.addColorStop(0,'rgba(0,0,0,.32)');halo.addColorStop(.62,'rgba(0,0,0,.14)');halo.addColorStop(1,'rgba(0,0,0,0)');ctx.fillStyle=halo;ctx.fillRect(0,0,width,height);ctx.strokeStyle=off?'rgba(255,255,255,.05)':`rgba(220,220,220,${.12+hover*.7})`;ctx.lineWidth=1.2;ctx.beginPath();ctx.roundRect(.8,.8,width-1.6,height-1.6,Math.min(15,height/2));ctx.stroke();if(!off){const burst=ripples.reduce((a,r)=>a+Math.max(0,1-(clock-r.time)/800),0);const angle=clock*.0007+mx*hover*.8+burst*Math.PI*2,beam=ctx.createConicGradient(angle,width/2,height/2);beam.addColorStop(0,'rgba(220,220,220,0)');beam.addColorStop(.75,'rgba(220,220,220,0)');beam.addColorStop(.91,`rgba(220,220,220,${.45+hover*.4})`);beam.addColorStop(1,'rgba(220,220,220,0)');ctx.strokeStyle=beam;ctx.lineWidth=1.6;ctx.stroke()}ripples=ripples.filter(r=>clock-r.time<850)}function tick(now){frame=null;if(!visible||document.hidden||!button.isConnected)return;const dt=last?Math.min(65,now-last):34;if(now-last>=1000/30){last=now;render(dt)}if(!button.disabled&&!reduced.matches)frame=requestAnimationFrame(tick)}function wake(){if(frame===null&&visible&&!document.hidden&&button.isConnected){last=0;if(reduced.matches||button.disabled)render(16);else frame=requestAnimationFrame(tick)}}function enter(e){if(button.disabled||reduced.matches)return;target=1;move(e);wake()}function move(e){if(!Number.isFinite(e.clientX))return;const r=button.getBoundingClientRect();mx=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width));my=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height))}function focus(){target=1;wake()}function leave(){target=0;wake()}function down(e){if(button.disabled||reduced.matches)return;move(e);ripples.push({x:mx*width,y:my*height,time:clock});wake()}function changed(){if(frame!==null)cancelAnimationFrame(frame);frame=null;hover=target=0;render(0);wake()}const resizeObserver=new ResizeObserver(resize);resizeObserver.observe(button);const viewObserver=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(!visible&&frame!==null){cancelAnimationFrame(frame);frame=null}else wake()});viewObserver.observe(button);const stateObserver=new MutationObserver(changed);stateObserver.observe(button,{attributes:true,attributeFilter:['disabled']});button.addEventListener('pointerenter',enter);button.addEventListener('pointermove',move,{passive:true});button.addEventListener('pointerleave',leave);button.addEventListener('pointerdown',down);button.addEventListener('focus',focus);button.addEventListener('blur',leave);document.addEventListener('visibilitychange',changed);reduced.addEventListener('change',changed);function destroy(){if(frame!==null)cancelAnimationFrame(frame);resizeObserver.disconnect();viewObserver.disconnect();stateObserver.disconnect();button.removeEventListener('pointerenter',enter);button.removeEventListener('pointermove',move);button.removeEventListener('pointerleave',leave);button.removeEventListener('pointerdown',down);button.removeEventListener('blur',leave);button.removeEventListener('focus',focus);document.removeEventListener('visibilitychange',changed);reduced.removeEventListener('change',changed);button.classList.remove('muse-pixel-button');canvas.remove()}resize()}function scan(){scanFrame=null;for(const [el,inst]of instances){if(!el.isConnected){inst.destroy();instances.delete(el)}else if(!el.contains(inst.canvas)){el.appendChild(inst.canvas)}}root.querySelectorAll('button.muse-create-action,button.quick-submit,button.sx-submit,button.sx-btn-primary').forEach(button=>{if(button.matches('.muse-create-action,.quick-submit,.sx-submit')||/^(?:Tạo|Create|Generate|MUSE viết|Tiếp tục · Viết|Continue · Write)/i.test(button.textContent.trim()))attach(button)})}const observer=new MutationObserver(()=>{if(scanFrame===null)scanFrame=requestAnimationFrame(scan)});observer.observe(root,{childList:true,subtree:true});scan();return()=>{observer.disconnect();if(scanFrame!==null)cancelAnimationFrame(scanFrame);for(const inst of instances.values())inst.destroy();instances.clear()}}
